args:
$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $m = Get-MpComputerStatus
$av = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct)
$on = @(); $old = @()
foreach ($a in $av) { $h = '{0:x6}' -f [int]$a.productState; $en = $h.Substring(2,2) -in @('10','11'); $cur = $h.Substring(4,2) -eq '00'; "AV: $($a.displayName), $(if($en){'on'}else{'off'}), $(if($cur){'up to date'}else{'out of date'})"; if ($en) { $on += $a.displayName; if (-not $cur) { $old += $a.displayName } } }
if ($m) { "DEFENDER: real-time $($m.RealTimeProtectionEnabled), definitions $($m.AntivirusSignatureAge) days old, tamper protection $($m.IsTamperProtected), mode $($m.AMRunningMode)" }
if (-not $av.Count -and $m) { if ($m.RealTimeProtectionEnabled) { $on += 'Microsoft Defender' }; if ($m.AntivirusSignatureAge -gt 7) { $old += 'Microsoft Defender' } }
if (-not $on.Count) { 'ANTIVIRUS_OFF' } elseif ($old.Count) { "ANTIVIRUS_OUTDATED: $($old -join ', ')" } else { "ANTIVIRUS_OK: $($on -join ', ')" }

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $p = Get-NetFirewallProfile; $p | ForEach-Object { "$($_.Name): $(if($_.Enabled){'on'}else{'off'})" }
$third = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName FirewallProduct | Where-Object { ('{0:x6}' -f [int]$_.productState).Substring(2,2) -in @('10','11') })
$off = @($p | Where-Object { -not $_.Enabled } | ForEach-Object { $_.Name })
if ($off.Count -and $third.Count) { "THIRD_PARTY_FIREWALL: $($third[0].displayName)" } elseif ($off.Count) { "FIREWALL_OFF: $($off -join ', ')" } else { 'FIREWALL_ON' }

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $s = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
if ($s.EnableLUA -eq 0) { 'UAC_OFF' } elseif ($s.ConsentPromptBehaviorAdmin -eq 0) { 'UAC_NEVER_NOTIFY' } else { 'UAC_ON' }
$e = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer').SmartScreenEnabled
$pol = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\System').EnableSmartScreen
if ($e -eq 'Off' -or $pol -eq 0) { 'SMARTSCREEN_OFF' } else { 'SMARTSCREEN_ON' }

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $se = (New-Object -ComObject Microsoft.Update.Session).CreateUpdateSearcher(); $n = $se.GetTotalHistoryCount()
$last = $null; if ($n -gt 0) { $last = $se.QueryHistory(0, [Math]::Min($n, 100)) | Where-Object { $_.ResultCode -eq 2 } | Sort-Object Date -Descending | Select-Object -First 1 }
if ((Get-Service wuauserv).StartType -eq 'Disabled') { 'SERVICE_DISABLED' }
if ((Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU').NoAutoUpdate -eq 1) { 'POLICY_DISABLED' }
$p = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings').PauseUpdatesExpiryTime
if ($p -and ([datetime]$p) -gt (Get-Date)) { "PAUSED_UNTIL: $(([datetime]$p).ToString('d'))" }
if ($last) { "LAST_UPDATE_DAYS: $([int]((Get-Date) - $last.Date).TotalDays) ($($last.Title))" } else { 'LAST_UPDATE_DAYS: unknown' }

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; try { $sb = Confirm-SecureBootUEFI -ErrorAction Stop; if ($sb) { 'SECUREBOOT_ON' } else { 'SECUREBOOT_OFF' } } catch { if ("$_" -match 'not supported') { 'LEGACY_BIOS' } else { 'SECUREBOOT_UNKNOWN' } }
$h = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity').Enabled
"MEMORY_INTEGRITY: $(if($h -eq 1){'on'}else{'off'})"

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $a = @(Get-LocalGroupMember -SID 'S-1-5-32-544' | ForEach-Object { $_.Name })
if (-not $a.Count) { $a = @((net localgroup administrators | Select-Object -Skip 6 | Where-Object { $_ -and $_ -notmatch 'command completed' })) }
"ADMINS: $($a -join ', ')"
if ((Get-LocalUser | Where-Object { $_.SID -like '*-501' }).Enabled) { 'GUEST_ENABLED' }
if ((Get-LocalUser | Where-Object { $_.SID -like '*-500' }).Enabled) { 'BUILTIN_ADMIN_ENABLED' }

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $ts = Get-ItemProperty 'HKLM:\System\CurrentControlSet\Control\Terminal Server'
if ($ts.fDenyTSConnections -eq 0) { 'RDP_ON' } else { 'RDP_OFF' }
if ($ts.fAllowToGetHelp -eq 1) { 'REMOTE_ASSISTANCE_ON' }
if ((Get-SmbServerConfiguration).EnableSMB1Protocol) { 'SMB1_ON' }

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $third = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct | Where-Object { $_.displayName -notmatch 'Defender' -and ('{0:x6}' -f [int]$_.productState).Substring(2,2) -in @('10','11') })
if ($third.Count) { "OTHER_ANTIVIRUS: $($third[0].displayName)"; exit 0 }
Set-MpPreference -DisableRealtimeMonitoring $false -ErrorAction Stop; 'DEFENDER_ON'

$ProgressPreference='SilentlyContinue'; $ErrorActionPreference='SilentlyContinue'; $k='HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings'; foreach ($n in 'PauseUpdatesExpiryTime','PauseUpdatesStartTime','PauseFeatureUpdatesStartTime','PauseFeatureUpdatesEndTime','PauseQualityUpdatesStartTime','PauseQualityUpdatesEndTime') { Remove-ItemProperty $k $n }
$a='HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU'; if ((Get-ItemProperty $a).NoAutoUpdate -eq 1) { Remove-ItemProperty $a NoAutoUpdate; 'POLICY_REMOVED' }
if ((Get-Service wuauserv).StartType -eq 'Disabled') { Set-Service wuauserv -StartupType Manual; 'SERVICE_ENABLED' }
Start-Service wuauserv; UsoClient.exe StartScan; 'UPDATES_RESUMED'
